/**
 * n8n Code node (JavaScript)
 * Input: items[0].json = full payload (array or object)
 * Output:
 *  - json.transcript_text (plain text)
 *  - json.message_count
 *  - binary.transcript.csv (CSV file for Google Sheets)
 */

function toISO(ts) {
  if (ts == null || ts === '') return '';
  // Numeric seconds/ms/µs
  if (typeof ts === 'number') {
    // Heuristics: s vs ms vs µs
    if (ts < 1e11) {               // probably seconds
      return new Date(ts * 1000).toISOString();
    } else if (ts < 1e15) {        // probably milliseconds
      return new Date(ts).toISOString();
    } else {                       // probably microseconds
      return new Date(Math.floor(ts / 1000)).toISOString();
    }
  }
  // String that might be ISO or numeric
  if (typeof ts === 'string') {
    const num = Number(ts);
    if (!Number.isNaN(num)) return toISO(num);
    const d = new Date(ts);
    if (!isNaN(d.getTime())) return d.toISOString();
  }
  return '';
}

function safeJoin(x) {
  if (x == null) return '';
  if (Array.isArray(x)) return x.map(safeJoin).filter(Boolean).join(' ');
  if (typeof x === 'object') return '';
  return String(x).trim();
}

function normalizeRole(v) {
  if (!v) return 'unknown';
  const s = String(v).toLowerCase();
  if (/(^|_|-)user|client|customer|speaker_?1|caller/.test(s)) return 'user';
  if (/assistant|agent|ai|bot|system|speaker_?2|ivr|voicebot/.test(s)) return 'agent';
  return s === 'human' ? 'user' : s === 'computer' ? 'agent' : 'unknown';
}

function pickText(obj) {
  // Common text fields
  const candidates = [
    'content','text','message','transcript','utterance','value','body','msg','data',
  ];
  for (const k of candidates) {
    if (obj[k] != null) {
      const val = safeJoin(obj[k]);
      // Avoid attaching giant base64/audio blobs as "text"
      if (val && val.length < 20000 && !/^[A-Za-z0-9+/=\s]+$/.test(val) /* avoid big base64 */) {
        return val;
      }
    }
  }
  return '';
}

function pickRole(obj) {
  const candidates = ['role','speaker','from','author','participant','sender','type'];
  for (const k of candidates) {
    if (obj[k] != null) return normalizeRole(obj[k]);
  }
  // ElevenLabs webhooks sometimes mark bot/user via nested keys; fallback later.
  return 'unknown';
}

function pickTs(obj) {
  const candidates = [
    'timestamp','event_timestamp','created_at','time','ts','start','end','offset_ms','started_at','ended_at',
  ];
  for (const k of candidates) {
    if (obj[k] != null && obj[k] !== '') return obj[k];
  }
  return undefined;
}

// Recursively traverse and collect message-like records.
function collectMessages(node, bucket, path = []) {
  if (node == null) return;

  if (Array.isArray(node)) {
    node.forEach((v, i) => collectMessages(v, bucket, path.concat([`[${i}]`])));
    return;
  }

  if (typeof node === 'object') {
    // Heuristic: object looks like a message if it has either a text-like field or a role + text
    const txt = pickText(node);
    let role = pickRole(node);
    const ts = pickTs(node);

    // Some payloads nest messages under known array keys
    const likelyArrays = ['messages','turns','segments','alternatives','entries','conversation','events','results','logs'];
    for (const k of likelyArrays) {
      if (Array.isArray(node[k])) collectMessages(node[k], bucket, path.concat([k]));
    }

    // If we found text, accept it as a message; role may be unknown
    if (txt) {
      bucket.push({
        ts,
        role,
        text: txt,
        // Keep a weak path order to stabilize sorting when timestamps are missing
        orderKey: path.join('.') + '|' + (bucket.length + 1),
      });
    } else {
      // Keep digging
      for (const [k, v] of Object.entries(node)) {
        if (v && typeof v === 'object') collectMessages(v, bucket, path.concat([k]));
      }
    }
  }
}

// Convert collected messages into sorted transcript
function buildTranscript(messages) {
  // Normalize timestamps (for sort) and roles
  const augmented = messages.map((m, i) => {
    const iso = toISO(m.ts);
    let sortTs;
    if (iso) sortTs = Date.parse(iso);
    return {
      ...m,
      role: normalizeRole(m.role),
      iso: iso || '',
      sortTs: typeof sortTs === 'number' && !Number.isNaN(sortTs) ? sortTs : Number.MAX_SAFE_INTEGER - (messages.length - i), // stable fallback
      orderIdx: i,
    };
  });

  augmented.sort((a, b) => {
    if (a.sortTs !== b.sortTs) return a.sortTs - b.sortTs;
    // Tie-breaker: stable by discovery order
    return a.orderIdx - b.orderIdx;
  });

  // Plain text transcript lines
  const lines = augmented.map(m => {
    const ts = m.iso ? `[${m.iso}] ` : '';
    const role = (m.role === 'user' || m.role === 'agent') ? m.role.toUpperCase() : 'UNKNOWN';
    return `${ts}${role}: ${m.text}`;
  });

  // CSV (timestamp_iso,role,text) — Escape quotes for Sheets
  const esc = (s) => `"${String(s ?? '').replace(/"/g, '""')}"`;
  const csvRows = [['timestamp_iso', 'role', 'text']]
    .concat(augmented.map(m => [m.iso, m.role, m.text]))
    .map(cols => cols.map(esc).join(','));

  return {
    text: lines.join('\n'),
    csv: csvRows.join('\n'),
    count: augmented.length,
  };
}

// ==== Main ====
const input = items[0]?.json ?? {};
const root = Array.isArray(input) && input.length === 1 ? input[0] : input;

const bucket = [];
collectMessages(root, bucket);

// If nothing found, try some common ElevenLabs locations
if (bucket.length === 0) {
  // Sometimes webhook wraps in { body: {...} }
  if (root.body) collectMessages(root.body, bucket);
  if (root.data) collectMessages(root.data, bucket);
}

const { text, csv, count } = buildTranscript(bucket);

// Attach CSV as binary for easy Google Sheets import (File → Import)
const binary = {};
binary['transcript'] = await this.helpers.prepareBinaryData(
  Buffer.from(csv, 'utf8'),
  'transcript.csv',
  'text/csv'
);

return [
  {
    json: {
      message_count: count,
      transcript_text: text, // plain text output
    },
    binary,
  },
];

